ee:message.ee:set-payload:
%dw 2.0
output application/json
var cabecera = vars.inputBody.ProgramacionPortacion.MensajeABD.CabeceraMensaje
---
{
  "MensajeABD": {
    "CabeceraMensaje": {
      "IdentificadorProceso": cabecera.IdentificadorProceso,
      "IdentificadorMensaje": vars.idMessage.consecutivo,
      "FechaCreacionMsg": cabecera.FechaCreacion,
      "TipoMsg": cabecera.TipoMensaje,
      "Emisor": cabecera.Emisor,
      "Observaciones": cabecera.Observaciones
    },
    "CuerpoMensaje": vars.inputBody.ProgramacionPortacion.MensajeABD.CuerpoMensaje
    }
}

